public class BinaryReader {

    public static int fromBinary(String bits) {
        int result = 0;
        for (int i = 0; i < bits.length(); i++) {
            int digit = bits.charAt(i) - '0';
            result = result * 2 + digit;
        }
        return result;
    }
}
